            ]
          }
        },
        "/v3/checkins": {
          "get": {
            "summary": "Cursor-paginated check-in feed",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/pings": {
          "get": {
            "summary": "Offset/limit ping feed",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/audit-events": {
          "get": {
            "summary": "Link-header (RFC5988) audit feed",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/stats/summary": {
          "get": {
            "summary": "Grand reconciliation totals",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/events": {
          "get": {
            "summary": "DEPRECATED legacy feed",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
  "updated_at": "2026-07-18T04:53:21.799901+00:00"
}

